module alu(
    input [31:0] a, b,
    input [5:0] aluc,
    output [31:0] r,
    output zero,
    output carry,
    output negative,
    output overflow,
    output flag
);
    // TODO: Please add your logic design here

    parameter ADD = 6'b100000;
    parameter ADDU = 6'b100001;
    parameter SUB = 6'b100010;
    parameter SUBU = 6'b100011;
    parameter AND = 6'b100100;
    parameter OR = 6'b100101;
    parameter XOR = 6'b100110;
    parameter NOR = 6'b100111;
    parameter SLT = 6'b101010;
    parameter SLTU = 6'b101011;
    parameter SLL = 6'b000000;
    parameter SRL = 6'b000010;
    parameter SRA = 6'b000011;
    parameter SLLV = 6'b000100;
    parameter SRLV = 6'b000110;
    parameter SRAV = 6'b000111;
    parameter LUI = 6'b001111;
    reg [32:0] res;
    wire [31:0] signed_a, signed_b;

    assign signed_a = a;
    assign signed_b = b;
    assign r = res[31:0];
    assign flag = (aluc == SLT || aluc == SLTU) ? res : 1'bz;
    assign zero = ~|res ? 1'b1 : 1'b0;
    assign carry = ~(aluc == SUB | aluc == SUBU) & ~(|res) ? 1'b1 : 1'b0;
    assign negative = ~((aluc == SUB | aluc == SUBU) & (~&res)) ? 1'b1 : 1'b0;
    assign overflow = ~((aluc == ADD | aluc == ADDU) & (res != signed_a + signed_b)) ? 1'b1 : 1'b0;
    always @(*) begin
        case(aluc)
            ADD: res = signed_a + signed_b;
            ADDU: res = a + b;
            SUB: res = signed_a - signed_b;
            SUBU: res = a - b;
            AND: res = a & b;
            OR: res = a | b;
            XOR: res = a ^ b;
            NOR: res = ~(a | b);
            SLT: res = signed_a < signed_b ? 1 : 0;
            SLTU: res = a < b ? 1 : 0;
            SLL: res = b << a[4:0]; // Shift left logical by a[4:0]
            SRL: res = b >> a[4:0]; // Shift right logical by a[4:0]
            SRA: res = b >>> a[4:0]; // Shift right arithmetic by a[4:0]
            SLLV: res = b << a[4:0]; // Shift left logical by a[4:0]
            SRLV: res = b >> a[4:0]; // Shift right logical by a[4:0]
            SRAV: res = b >>> a[4:0]; // Shift right arithmetic by a[4:0]
            LUI: res = {a[15:0], 16'd0};
            default: res = 32'dz; // Default case to handle undefined values
        endcase
    end
endmodule
